// ---- outils (à ajouter près de sectorMovers) ----------------------------
/** Mobilité nulle jusqu'à t0 (partie tenue), puis linéaire jusqu'à la pointe. */
const after = (t0: number) => (t: number) => clamp((t - t0) / Math.max(1e-3, 1 - t0), 0, 1)

/** Fraction de longueur (sur les cordes) d'un tracé à l'indice k. */
function arcAt(pts: THREE.Vector3[], k: number) {
  let at = 0, total = 0
  for (let i = 1; i < pts.length; i++) {
    const d = pts[i].distanceTo(pts[i - 1])
    total += d
    if (i <= k) at += d
  }
  return total > 0 ? at / total : 0
}

/** Repousse radialement hors du crâne : pour ce qui retombe autour du sommet. */
function clearSkull(p: DollParams, q: THREE.Vector3, margin: number) {
  const need = onDir(p, q.clone().normalize(), margin).pos.length()
  if (q.length() < need) q.setLength(need)
  return q
}

/** Plus grande largeur du crâne (bajoues comprises), en rayons de tête. */
function widest(p: DollParams) {
  let w = 0
  for (let sy = -0.7; sy <= 0.31; sy += 0.05)
    for (const az of [0, Math.PI / 2]) {
      const q = onHeadPolar(p, az, sy, 0).pos
      w = Math.max(w, Math.hypot(q.x, q.z))
    }
  return w / p.shape.headRadius
}

/** Ressort pivotant au centre, bout vers l'azimut az (hors de l'axe de rotation). */
function centerMover(R: number, az: number, stiffness: number, drag: number, maxAngle: number): Mover {
  return {
    pivot: new THREE.Vector3(),
    dir: new THREE.Vector3(Math.sin(az) * 0.75, -0.66, Math.cos(az) * 0.75).normalize(),
    length: R,
    cfg: { stiffness, drag, gravity: 0 },
    maxAngle,
  }
}

// ---- houppette -----------------------------------------------------------
function tuft(p: DollParams, rnd: () => number, yarnR: number, out: Parts) {
  const R = p.shape.headRadius
  const r = yarnR * (1 + rnd() * 0.35)
  // Nœud au sommet, un peu en arrière : devant, les lames retomberaient sur la frange.
  const knotAz = Math.PI + (rnd() - 0.5) * 0.6
  const knotSy = 0.9 + rnd() * 0.06
  const s = onHeadPolar(p, knotAz, knotSy, 0)
  const n = s.normal
  const kd = dirOf(knotAz, knotSy)
  const [e1, e2] = tangentBasis(kd)
  const tieR = r * 4.2
  const W0 = widest(p)
  out.ribbonColor = RIBBONS[Math.floor(rnd() * RIBBONS.length)]

  // 1. Cheveux TIRÉS vers le nœud : tenus, aucun ressort.
  const limit = hairline(p, NAPE_LOW + rnd() * 0.12, 1.7)
  const edgeOf = (az: number) => limit(az) - Math.max(0, -Math.cos(az)) ** 3 * 0.18
  // Répartis en azimut autour du NŒUD, comptés sur le grand cercle à 90° (là où les géodésiques s'écartent le plus).
  const count = clamp(Math.ceil((2 * Math.PI * R * W0) / (0.8 * 2 * r)), 60, 260)
  const grooves = 12 + Math.floor(rnd() * 5)
  for (let i = 0; i < count; i++) {
    const outer = i % 2 === 1 // couche B, décalée d'un demi-pas
    const phi = ((i + 0.5 + (rnd() - 0.5) * 0.2) / count) * Math.PI * 2
    const lift = outer
      ? r * (1.6 + 0.9 * (0.5 + 0.5 * Math.cos(phi * grooves)) + rnd() * 0.2) // crêtes de tension
      : r * (0.9 + rnd() * 0.2)
    const way = e1.clone().multiplyScalar(Math.cos(phi)).addScaledVector(e2, Math.sin(phi))
    let from: THREE.Vector3 | null = null
    let th = 0.05
    for (; th < Math.PI; th += 0.01) {
      const d = kd.clone().multiplyScalar(Math.cos(th)).addScaledVector(way, Math.sin(th))
      if (d.y < edgeOf(Math.atan2(d.x, d.z))) break
      from = d
    }
    if (!from || th < 0.25) continue // tirages déjà faits
    const end = s.pos.clone().addScaledVector(way, tieR * 0.8).addScaledVector(n, r * 1.5).normalize()
    const pts: THREE.Vector3[] = []
    for (let k = 0; k <= 22; k++)
      pts.push(onDir(p, from.clone().lerp(end, k / 22).normalize(), k === 0 ? -r * 2 : lift).pos)
    pts.push(s.pos.clone().addScaledVector(n, r * 2)) // finit sous le chouchou : l'effilage y disparaît
    out.yarn.push(yarn(pts, r)) // mover −1, aFree = aFling = 0
  }
  for (let w = 0; w < 2; w++)
    out.ribbon.push(ring(s.pos.clone().addScaledVector(n, r * (2.2 + w * 2.6)), n, tieR + r * (1.6 - w * 0.2), r * 1.4))

  // 2. Frange en pointes (brique de bangs()), racines sous la couche tenue.
  const front = limit(0)
  const edge = hairline(p, 0, 1.1)(0)
  const W = 0.62 + rnd() * 0.12
  const T = 3 + Math.floor(rnd() * 3)
  const fringe0 = out.movers.length
  for (let k = 0; k < T; k++)
    out.movers.push(centerMover(R, (((k + 0.5) / T) * 2 - 1) * W * 0.9, 0.025 + rnd() * 0.02, 0.06 + rnd() * 0.05, 0.18))
  const tuftLen = Array.from({ length: T }, () => rnd())
  const nb = 2 * Math.ceil((2 * W * R * Math.sqrt(1 - front * front) * W0) / (1.6 * r))
  for (let i = 0; i < nb; i++) {
    const u = (i + 0.5) / nb
    const f = clamp(u * T + (i % 2 ? 0.5 : 0) - 0.25, 0, T - 0.001)
    const c = Math.floor(f)
    const w = (f - c) * 2 - 1
    const az = (u * 2 - 1) * W
    const center = (((c + 0.5) / T) * 2 - 1) * W * 0.9
    const tipAz = az + (center - az) * 0.6
    const side = Math.abs(tipAz) / W
    const tipSy = edge + tuftLen[c] * 0.05 + Math.abs(w) ** 1.5 * 0.06 + side * side * 0.06 + rnd() * 0.015
    const layer = r * (0.8 + rnd() * 1.6)
    const phase = rnd() * 6
    const from = dirOf(az, edgeOf(az) + 0.07)
    const tip = dirOf(tipAz, clamp(tipSy, -0.9, 0.9))
    if (from.angleTo(tip) < 0.08) continue // trop courte pour exister
    const pts: THREE.Vector3[] = []
    let hang: THREE.Vector3 | null = null
    for (let k = 0; k <= 12; k++) {
      const t = k / 12
      const lift = k === 0 ? -r * 2
        : Math.min(layer, r * 0.6 + ((layer - r * 0.6) * t) / 0.3) + R * 0.04 * Math.max(0, (t - 0.8) / 0.2) ** 2
      const q = onDir(p, from.clone().lerp(tip, t).normalize(), lift).pos
      if (t > 0.5) { // tombante, comme bangs()
        hang ??= pts[pts.length - 1].clone()
        if (hang.z > q.z) q.z += (hang.z - q.z) * 0.7
      }
      pts.push(q)
    }
    out.yarn.push(yarn(pts, r, { mover: fringe0 + c, free: after(0.2), fling: after(0.2), phase }))
  }

  // 3. Mèches latérales qui encadrent le visage (chiralité signée par sx).
  for (const sx of [-1, 1]) {
    const azS = sx * (1.1 + rnd() * 0.2)
    const sy0 = 0.26 + rnd() * 0.08
    const endSy = -0.72 - rnd() * 0.1
    const m = out.movers.length
    out.movers.push(centerMover(R, azS, 0.025 + rnd() * 0.015, 0.06 + rnd() * 0.04, 0.35))
    const ns = 12 + Math.floor(rnd() * 5)
    const edgeS = edgeOf(azS)
    for (let j = 0; j < ns; j++) {
      const az = azS + (((j + 0.5) / ns) * 2 - 1) * 0.1
      const base = r * (1 + (j % 2) * 1.1 + rnd() * 0.3)
      const phase = rnd() * 6
      const pts: THREE.Vector3[] = []
      let rMax = 0
      for (let k = 0; k <= 16; k++) {
        const t = k / 16
        const close = 0.85 * clamp((t - 0.45) / 0.55, 0, 1) ** 1.3
        const a = az + (azS - az) * close - sx * 0.14 * Math.max(0, (t - 0.75) / 0.25) ** 2
        const sy = sy0 + (endSy - sy0) * t
        // Par-dessus la couche tenue tant qu'on est au-dessus de sa lisière.
        const over = r * 3.8 * THREE.MathUtils.smoothstep(sy, edgeS - 0.12, edgeS + 0.04)
        const q = onHeadPolar(p, a, sy, k === 0 ? -r * 2 : base + over + R * 0.05 * Math.sin(Math.PI * t)).pos
        const h = Math.hypot(q.x, q.z)
        if (sy < 0 && h < rMax) { q.x *= rMax / h; q.z *= rMax / h }
        rMax = Math.max(rMax, Math.hypot(q.x, q.z))
        pts.push(q)
      }
      out.yarn.push(yarn(pts, r, { mover: m, free: after(0.15), fling: after(0.15), phase }))
    }
  }

  // 4. Palmier : lames pointues en fontaine, un ressort par lame.
  const K = 6 + Math.floor(rnd() * 3)
  const L = R * (0.5 + rnd() * 0.25)
  const ringTop = s.pos.clone().addScaledVector(n, r * 6)
  const stemTop = ringTop.clone().addScaledVector(n, R * (0.06 + rnd() * 0.06))
  const phi0 = rnd() * Math.PI * 2
  const ways = Array.from({ length: K }, (_, c) => {
    const phi = phi0 + ((c + 0.5 + (rnd() - 0.5) * 0.35) / K) * Math.PI * 2
    return e1.clone().multiplyScalar(Math.cos(phi)).addScaledVector(e2, Math.sin(phi))
  })
  // Lame héroïque (épi) : la plus tournée vers l'avant — choisie par la géométrie, aucun tirage conditionnel.
  const hero = ways.reduce((b, w, c) => (w.z > ways[b].z ? c : b), 0)
  const spike0 = out.movers.length
  ways.forEach((way, c) => {
    const isHero = c === hero
    const side = new THREE.Vector3().crossVectors(n, way).normalize()
    const Lc = L * (0.75 + rnd() * 0.5) * (isHero ? 1.3 : 1)
    const rise = Lc * (isHero ? 0.55 : 0.3 + rnd() * 0.2)
    let drop = Lc * (isHero ? 0.1 : 0.35 + rnd() * 0.3)
    const wc = r * (3.5 + rnd() * 1.5)
    const nc0 = 8 + Math.floor(rnd() * 3)
    const nc = isHero ? 5 : nc0
    const axis = (u: number) => stemTop.clone()
      .addScaledVector(way, Lc * 0.8 * u)
      .addScaledVector(n, 4 * rise * u * (1 - u) - drop * u * u + r * 4 * Math.max(0, (u - 0.82) / 0.18) ** 2)
    // Garde-fou : une lame de devant ne descend pas sous la racine de la frange.
    for (let g = 0; g < 6; g++) {
      const d = axis(1).normalize()
      if (d.z <= 0 || d.y >= front + 0.1) break
      drop *= 0.7
    }
    const tipRest = axis(1)
    out.movers.push({
      pivot: stemTop.clone(),
      dir: tipRest.clone().sub(stemTop).normalize(),
      length: tipRest.distanceTo(stemTop),
      cfg: { stiffness: (0.06 + rnd() * 0.04) * (isHero ? 1.5 : 1), drag: isHero ? 0.05 : 0.07 + rnd() * 0.05, gravity: 0 },
      maxAngle: 0.45,
    })
    for (let j = 0; j < nc; j++) {
      const ang = j * GOLDEN
      const rad = Math.sqrt((j + 0.5) / nc)
      const oa = Math.cos(ang) * rad
      const ob = Math.sin(ang) * rad * 0.55 // lame aplatie
      const pts: THREE.Vector3[] = [
        s.pos.clone().addScaledVector(n, -r * 2),
        ringTop.clone().addScaledVector(way, tieR * 0.55 * rad).addScaledVector(side, tieR * 0.4 * oa),
      ]
      for (let k = 1; k <= 14; k++) {
        const u = k / 14
        const wid = wc * (u < 0.3 ? 0.4 + (0.6 * u) / 0.3 : 1) * (1 - 0.85 * clamp((u - 0.45) / 0.55, 0, 1) ** 1.3)
        pts.push(clearSkull(p, axis(u).addScaledVector(side, oa * wid).addScaledVector(n, ob * wid), r * 2))
      }
      const t0 = arcAt(pts, 1) // bout du chouchou
      out.yarn.push(yarn(pts, r, { mover: spike0 + c, free: after(t0), fling: after(t0), phase: rnd() * 6 }))
    }
  })
  // Cœur : brins courts dressés, sur le ressort de la lame la plus proche, à demi-mobilité.
  const core = 6 + Math.floor(rnd() * 5)
  for (let i = 0; i < core; i++) {
    const lean = e1.clone().multiplyScalar(rnd() - 0.5).addScaledVector(e2, rnd() - 0.5)
    const h = L * (0.2 + rnd() * 0.25)
    const pts = [
      s.pos.clone().addScaledVector(n, -r * 2),
      ringTop.clone(),
      stemTop.clone().addScaledVector(n, h * 0.6).addScaledVector(lean, h * 0.3),
      stemTop.clone().addScaledVector(n, h).addScaledVector(lean, h * 0.7),
    ]
    const near = ways.reduce((b, w, c) => (w.dot(lean) > ways[b].dot(lean) ? c : b), 0)
    const t0 = arcAt(pts, 1)
    out.yarn.push(yarn(pts, r, { mover: spike0 + near, free: (t) => 0.5 * after(t0)(t), fling: (t) => 0.5 * after(t0)(t), phase: rnd() * 6 }))
  }
}
// Ressorts : T (3-5) + 2 + K (6-8) = 11 à 15, toujours ≤ MAX_MOVERS. Aucun changement à hairShader ni à Hairdo.

couettes.codeSketch:
// === hairstyles.tsx — outils ===
const smooth = (a: number, b: number, x: number) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t) }

// onDir : 0,9995 et non 0,98 (trou de 0,2 R au sommet ; dessus 86 % → 97 %)
function onDir(p: DollParams, d: THREE.Vector3, lift: number) {
  return onHeadPolar(p, Math.atan2(d.x, d.z), clamp(d.y, -0.9995, 0.9995), lift)
}

// YarnOpts : + step?: number   (anneau tous les `step` rayons, 3 par défaut)
//   dans yarn() : const segs = clamp(Math.ceil(len / (radius * (o.step ?? 3))), 6, 48)

/** Directions régulièrement espacées EN LONGUEUR RÉELLE le long d'une ligne du crâne. */
function alongSkull(p: DollParams, line: THREE.Vector3[], pitch: number, offset = 0): THREE.Vector3[] {
  const pos = line.map((d) => onDir(p, d, 0).pos)
  const cum = [0]
  for (let i = 1; i < pos.length; i++) cum.push(cum[i - 1] + pos[i].distanceTo(pos[i - 1]))
  const total = cum[cum.length - 1], n = Math.max(1, Math.round(total / pitch))
  const out: THREE.Vector3[] = []
  for (let k = 0, j = 0; k < n; k++) {
    const s = ((k + 0.5 + offset) / n) * total
    while (j < cum.length - 2 && cum[j + 1] < s) j++
    const f = clamp((s - cum[j]) / Math.max(1e-9, cum[j + 1] - cum[j]), 0, 1)
    out.push(line[j].clone().lerp(line[j + 1], f).normalize())
  }
  return out
}

// === pulled : TENUS, densité déduite ===
function pulled(p: DollParams, rnd: () => number, r: number, targets: THREE.Vector3[], out: Parts, low: number, rim = r * 2.6) {
  const limit = hairline(p, low), R = p.shape.headRadius, M = 14
  const dirs = targets.map((t) => t.clone().normalize())
  const nearest = (f: THREE.Vector3) => dirs.reduce((a, d) => (d.dot(f) > a.dot(f) ? d : a), dirs[0])
  const rimAng = (rim + r) / R
  const strand = (from: THREE.Vector3, to: THREE.Vector3, lift: number) => {
    const axis = new THREE.Vector3().crossVectors(to, from).normalize()
    const edge = to.clone().applyAxisAngle(axis, rimAng)             // s'arrête au bord du ruban…
    const pts: THREE.Vector3[] = []
    for (let k = 0; k <= M; k++) pts.push(onDir(p, from.clone().lerp(edge, k / M).normalize(), k === 0 ? -r * 2 : lift).pos)
    pts.push(onDir(p, to.clone().applyAxisAngle(axis, rimAng * 0.4), -r * 2).pos) // …et plonge dessous
    out.yarn.push(yarn(pts, r, { step: 6 }))                           // pas de mover : aFree = aFling = 0
  }
  const pitch = r * 4
  const line = Array.from({ length: 721 }, (_, i) => {
    const az = -Math.PI + (i / 720) * Math.PI * 2
    return dirOf(az, limit(az) + 0.02 - Math.max(0, -Math.cos(az)) ** 3 * 0.18)
  })
  const lift = (layer: number) => r * (layer ? 1.4 : 0.5) + r * 0.3 * rnd()
  for (let layer = 0; layer < 2; layer++)
    for (const f of alongSkull(p, line, pitch, layer * 0.5)) {
      const j = dirOf(Math.atan2(f.x, f.z), clamp(f.y + (rnd() - 0.5) * 0.03, -0.98, 0.98))
      strand(j, nearest(j), lift(layer))
    }
  if (dirs.length === 2 && dirs[0].x * dirs[1].x < 0) {
    const a0 = Math.asin(limit(0)), a1 = Math.PI - Math.asin(Math.max(-0.9, limit(Math.PI) - 0.1))
    const mer = Array.from({ length: 201 }, (_, i) => { const a = a0 + (i / 200) * (a1 - a0); return new THREE.Vector3(0, Math.sin(a), Math.cos(a)) })
    for (let layer = 0; layer < 2; layer++)
      for (const f of alongSkull(p, mer, pitch, layer * 0.5))
        for (const d of dirs) strand(f.clone().add(new THREE.Vector3(Math.sign(d.x) * 0.02, 0, 0)).normalize(), d, lift(layer))
  }
}

// === queue en mèches (remplace bunch pour les couettes ; la queue de cheval peut l'appeler avec clumps: 6, side: 1) ===
type TailOpts = { clumps: number; bulge: number; bow: number; twist: number; side: -1 | 1 }
function tail(p: DollParams, rnd: () => number, r: number, tie: { pos: THREE.Vector3; normal: THREE.Vector3 }, L: number, out: Parts, o: TailOpts) {
  const R = p.shape.headRadius, stand = R * (0.16 + rnd() * 0.08), tight = r * 2.6
  const outH = new THREE.Vector3(tie.normal.x, 0, tie.normal.z).normalize()
  const knot = tie.pos.clone().addScaledVector(tie.normal, r * 2)
  const axisAt = (t: number) => tie.pos.clone()
    .addScaledVector(tie.normal, r * 2 + stand * Math.min(1, t * 2.5) ** 0.7)
    .addScaledVector(outH, o.bow * Math.sin(Math.PI * clamp(t, 0, 1)))
    .addScaledVector(DOWN, L * Math.max(0, t - 0.08) ** 1.25)
  const rho = (t: number) => tight + (o.bulge - tight) * smooth(0.04, 0.4, t)
  const m0 = out.movers.length
  for (let c = 0; c <= o.clumps; c++) out.movers.push({
    pivot: knot.clone(), dir: DOWN.clone(), length: L,
    cfg: { stiffness: (c === o.clumps ? 0.055 : 0.035) * (0.8 + rnd() * 0.4), drag: 0.12 + rnd() * 0.08, gravity: 1.0 + rnd() * 0.4 },
    maxAngle: 0.75,
  })
  const clumpLen = Array.from({ length: o.clumps + 1 }, () => 0.8 + rnd() * 0.22); clumpLen[o.clumps] = 1.02
  const count = Math.ceil(((2 * Math.PI * o.bulge) / (1.8 * r)) * 1.5)
  const N = 18, span = (Math.PI * 2) / o.clumps
  const free = (t: number) => smooth(0.06, 0.3, t) * (0.25 + 0.75 * t)
  for (let i = 0; i < count; i++) {
    const core = i % 6 === 5
    const a = (i * GOLDEN) % (Math.PI * 2)
    const s = core ? 0.35 * Math.sqrt(rnd()) : 0.55 + 0.45 * Math.sqrt(rnd())
    const c = core ? o.clumps : Math.floor(a / span)
    const ac = (c + 0.5) * span
    const tEnd = clumpLen[c] * (0.9 + rnd() * 0.1)
    const flick = rnd() < 0.5 ? 1 : 0.3                                  // tiré même pour le cœur
    const pts = [tie.pos.clone().addScaledVector(tie.normal, -r * 2)]
    for (let k = 1; k <= N; k++) {
      const t = (k / N) * tEnd, u = t / tEnd, tw = o.side * o.twist * t   // chiralité signée
      const tan = axisAt(Math.min(1.1, t + 0.02)).sub(axisAt(Math.max(0, t - 0.02))).normalize()
      const [b1, b2] = tangentBasis(tan)
      const close = 0.78 * smooth(0.5, 1, u) ** 1.2
      const own = b1.clone().multiplyScalar(Math.cos(a + tw)).addScaledVector(b2, Math.sin(a + tw)).multiplyScalar(s)
      const cc = core ? new THREE.Vector3() : b1.clone().multiplyScalar(Math.cos(ac + tw)).addScaledVector(b2, Math.sin(ac + tw))
      const off = own.lerp(cc.clone().multiplyScalar(0.62), close).multiplyScalar(rho(t))
      if (!core) off.addScaledVector(cc, flick * r * 3 * Math.max(0, (u - 0.8) / 0.2) ** 2)
      pts.push(clearHead(p, axisAt(t).add(off), r * 2.5))
    }
    out.yarn.push(yarn(pts, r, { mover: m0 + c, free, fling: free, phase: rnd() * 6 }))
  }
  const kc = axisAt(0.05), ax = axisAt(0.12).sub(axisAt(0)).normalize()
  out.ribbon.push(ring(kc, ax, tight + r * 1.6, r * 1.4))              // tenu (pas de mover)
  bowKnot(p, rnd, r, kc, tie.normal, o.side, out, m0 + o.clumps)       // boucles fixes, pans sur le cœur
}

// bowKnot(p, rnd, r, at: Vector3, n: Vector3, side: -1|1, out: Parts, coreMover: number)
//   deux boucles fermées en goutte dans le plan ⟂ n (x = l·(1−cosθ)/2, y = 0,45·l·sinθ·√(x/l)), l = R·(0,12..0,18), yarn(…, r*1.6, { closed: true }) → sans mover ;
//   deux pans ouverts (DOWN + outH·0,3, longueur 0,6..0,9 l) : yarn(…, r*1.5, { mover: coreMover, free: (t) => 0.6 * t }).

// fringeTufts(p, rnd, r, out, o: { width: number; tufts: number; edge: (az: number) => number })
//   = boucle de frange de bangs() copiée SANS toucher bangs : racines sur la raie
//   new Vector3(sign·0.03, 1, cos(tipAz)·0.55 − 0.12).normalize(), deux rangs (shift 0 / 0.5),
//   tipAz = az + (center − az)·0.6, tipSy = o.edge(tipAz) + tuftLen[c]·0.04 + |w|^1.5·0.07 + rnd()·0.015 (pas de `lengthen`),
//   count = 2 * alongSkull(p, tipLine, r * 1.8).length ; un mover par mèche : pivot (0,0,0), dir vers la mèche,
//   cfg { stiffness: 0.03 + rnd()*0.02, drag: 0.08 + rnd()*0.04, gravity: 0 }, maxAngle 0.08 ;
//   yarn(pts, r * 1.1, { mover: f0 + c, free: (t) => 0.7 * smooth(0.15, 0.55, t) * (0.3 + 0.7 * t), fling: (t) => 0.4 * t * t, phase }).

// sidelock(p, rnd, r, out, side: -1 | 1, edge: (az: number) => number)
//   az0 = side·clamp(asin(clamp((p.face.eyeSpacing/2 + size·1.3)/(1.02·R), 0, 0.95)) + 0.12, 0.95, 1.25), size = max(leftSize,rightSize)·EYE_SCALE·1.14
//   10 brins (2 couches × 5) sur une largeur r·(7..9) : 9 points sur le crâne de edge(az0) à p.shape.headCheekY (rayon jamais décroissant,
//   comme braids), puis 6 points qui pendent jusqu'à −ry − R·(0,08..0,18), refermés (0,85·t^1,3), pointe tournée de −side·0,12·t² autour de UP, clearHead(…, r*2) ;
//   mover { pivot: leave, dir: DOWN, length: leave.y − bottom, cfg { 0.05, 0.15, 1.0 }, maxAngle 0.35 } ; free = fling = clamp((t − 8/14)/(6/14), 0, 1) ** 1.2.

// ahoge(p, rnd, r, out) : racine onHeadPolar(p, π + (rnd()−0.5)·0.6, 0.985, 0) ; 3 brins r*1.1 convergeant sur un crochet
//   (montée H = R·(0,22..0,34), avancée F = R·(0,14..0,22), pointe qui retombe) ;
//   mover { pivot: racine, dir: (milieu − racine).normalize(), length: |milieu − racine|, cfg { 0.18, 0.06, 0 }, maxAngle 0.5 } ; free = t ** 1.3, fling = t.

// === couettes ===
function pigtails(p: DollParams, rnd: () => number, yarnR: number, out: Parts) {
  const R = p.shape.headRadius, r = yarnR * 0.9
  const sy = 0.4 + rnd() * 0.3
  const L = R * (0.75 + rnd() * 0.5)
  const back = 0.25 + rnd() * 0.15
  const ties = [-1, 1].map((sx) => onHeadPolar(p, sx * (Math.PI / 2 + back), sy, 0))
  out.ribbonColor = RIBBONS[Math.floor(rnd() * RIBBONS.length)]
  const hasAhoge = rnd() < 0.5                                        // tiré dans tous les cas
  const tufts = rnd() < 0.5 ? 5 : 7
  const bulge = r * (8 + rnd() * 3), bow = R * (0.05 + rnd() * 0.05), twist = 0.3 + rnd() * 0.5
  const edge = hairline(p, 0.15, 2.45)
  pulled(p, rnd, r, ties.map((t) => t.pos), out, NAPE_LOW + rnd() * 0.12, r * 2.6)
  const azSide = clamp(Math.asin(clamp((p.face.eyeSpacing * 0.5 + Math.max(p.face.leftSize, p.face.rightSize) * EYE_SCALE * 1.14 * 1.3) / (1.02 * R), 0, 0.95)) + 0.12, 0.95, 1.25)
  fringeTufts(p, rnd, r, out, { width: azSide - 0.05, tufts, edge })
  for (const s of [-1, 1] as const) sidelock(p, rnd, r, out, s, edge)
  ties.forEach((t, i) => tail(p, rnd, r, t, L, out, { clumps: 5, bulge, bow, twist, side: i ? 1 : -1 }))
  const ahogeRnd = mulberry32(Math.floor(rnd() * 1e9))                 // sous-graine : la suite ne dépend pas de hasAhoge
  if (hasAhoge) ahoge(p, ahogeRnd, r, out)
}

nattes.codeSketch:
// ---- imports en plus
import { onHeadPolar, armSpheres } from './surface'
import { dollLayout } from './layout'
const smooth = (x: number) => { const t = clamp(x, 0, 1); return t * t * (3 - 2 * t) }

// ---- yarn : pas d'anneaux réglable (brins épais de la natte : un anneau tous les 0,8 rayon)
type YarnOpts = { /* …existant… */ step?: number }
// dans yarn() :
const segs = clamp(Math.ceil(len / (radius * (o.step ?? 3))), 6, o.step !== undefined ? 128 : 48)

// ---- onDir : borne du pôle en paramètre (0,98 par défaut → grande frange inchangée)
function onDir(p: DollParams, d: THREE.Vector3, lift: number, cap = 0.98) {
  return onHeadPolar(p, Math.atan2(d.x, d.z), clamp(d.y, -cap, cap), lift)
}

/**
 * Cheveux tirés : TENUS (aucun ressort), racines uniformes en longueur d'arc sur le
 * bord de chaque zone, deux couches alternées au-dessus des fibres du duvet.
 * n = ceil(B / (spacing·r)) ; à 1,8r le cuir chevelu est couvert à 99,6 %.
 */
function pulled(
  p: DollParams, rnd: () => number, r: number, targets: THREE.Vector3[], out: Parts, low: number,
  o: { spacing?: number; tuck?: number } = {},
) {
  const R = p.shape.headRadius
  const limit = hairline(p, low)
  const dirs = targets.map((t) => t.clone().normalize())
  const nearest = (from: THREE.Vector3) => dirs.reduce((a, d) => (d.dot(from) > a.dot(from) ? d : a))
  const rim = (az: number) => dirOf(az, limit(az) + 0.02 - Math.max(0, -Math.cos(az)) ** 3 * 0.18)
  const split = dirs.length === 2 && dirs[0].x * dirs[1].x < 0
  const a0 = Math.asin(limit(0))
  const a1 = Math.PI - Math.asin(Math.max(-0.9, limit(Math.PI) - 0.1))
  const zones: { to: THREE.Vector3 | null; line: THREE.Vector3[] }[] = split
    ? dirs.map((to) => {
        const s = Math.sign(to.x)
        const part = Array.from({ length: 61 }, (_, k) => {
          const a = a0 + ((a1 - a0) * k) / 60
          return new THREE.Vector3(s * 0.02, Math.sin(a), Math.cos(a)).normalize()
        })
        const edge = Array.from({ length: 89 }, (_, k) => rim(s * (Math.PI - (Math.PI * (k + 1)) / 90)))
        return { to, line: [...part, ...edge] }
      })
    : [{ to: dirs.length === 1 ? dirs[0] : null, line: Array.from({ length: 181 }, (_, k) => rim((k / 180) * Math.PI * 2)) }]
  // Sommet du fil du dessous au-dessus de la pointe des fibres (shell.height).
  const base = Math.max(r * 0.8, p.shell.height - r * 0.9)
  const stop = (o.tuck ?? 0) / R
  for (const z of zones) {
    const cum = [0]
    for (let i = 1; i < z.line.length; i++) cum.push(cum[i - 1] + z.line[i].angleTo(z.line[i - 1]) * R)
    const B = cum[cum.length - 1]
    const n = Math.ceil(B / ((o.spacing ?? 1.8) * r))
    for (let i = 0; i < n; i++) {
      const at = ((i + 0.5 + (rnd() - 0.5) * 0.3) / n) * B
      let j = 1
      while (j < cum.length - 1 && cum[j] < at) j++
      const from = z.line[j - 1].clone().lerp(z.line[j], (at - cum[j - 1]) / (cum[j] - cum[j - 1])).normalize()
      const to = z.to ?? nearest(from)
      const layer = i % 2 ? base + r * (0.9 + rnd() * 0.3) : base * (1 + rnd() * 0.2)
      const ang = from.angleTo(to)
      const reach = Math.max(0.2, 1 - stop / Math.max(ang, 1e-3))
      const M = clamp(Math.ceil(ang / 0.08), 6, 24)
      const pts: THREE.Vector3[] = []
      for (let k = 0; k <= M; k++) {
        const d = from.clone().lerp(to, (k / M) * reach).normalize()
        const lift = k === 0 ? -r * 2 : k === M && stop > 0 ? -r * 0.5 : layer
        pts.push(onDir(p, d, lift, 0.999).pos)
      }
      out.yarn.push(yarn(pts, r)) // mover −1, aFree 0, aFling 0 : tenus
    }
  }
}

/**
 * Frange en mèches pointues, extraite TELLE QUELLE de bangs() (l. 1166-1272) :
 * même ordre de tirages. bangs() l'appelle avec
 *   { width, tufts, edge, sideTo: longEnd, over: (s) => FRINGE_OVER * R * clamp((s - 0.35) / 0.5, 0, 1),
 *     count: () => 110 + Math.floor(rnd() * 20), radius: r * 1.15,
 *     cfg: () => ({ stiffness: 0.018 + rnd() * 0.02, drag: 0.05 + rnd() * 0.05, gravity: 0 }),
 *     maxAngle: 0.42, free: (t) => 0.4 + 0.6 * t, fling: (t) => t }
 * Ordre à respecter : ressorts (cfg), rnd() « toujours effilée », count(), tuftLen, puis la boucle
 * (tipSy, from, layer, phase).
 */
function fringeTufts(p: DollParams, rnd: () => number, r: number, out: Parts, o: {
  width: number; tufts: number; edge: number; sideTo: number
  over: (side: number) => number; count: () => number; radius: number
  cfg: () => SpringConfig; maxAngle: number
  free: (t: number) => number; fling: (t: number) => number
}): void { /* corps de bangs() l. 1179-1272, longEnd → o.sideTo, r*1.15 → o.radius */ }

/** Mèche latérale : de la raie à la mâchoire, devant l'oreille, pointe rentrée vers la joue. */
function sideLock(p: DollParams, rnd: () => number, r: number, out: Parts,
  sx: 1 | -1, az: number, endSy: number, lay: number) {
  const R = p.shape.headRadius
  const m = out.movers.length
  out.movers.push({
    pivot: new THREE.Vector3(),
    dir: new THREE.Vector3(Math.sin(az) * 0.75, -0.66, Math.cos(az) * 0.75).normalize(),
    length: R,
    cfg: { stiffness: 0.03 + rnd() * 0.015, drag: 0.08 + rnd() * 0.04, gravity: 0 },
    maxAngle: 0.3,
  })
  const n = 14, M = 18, span = 0.24, tipAz = az - sx * 0.1
  for (let i = 0; i < n; i++) {
    const u = ((i + 0.5) / n) * 2 - 1
    const a0 = az + u * span * 0.5
    const from = new THREE.Vector3(sx * 0.03, 1, Math.cos(a0) * 0.55 - 0.12 + (rnd() - 0.5) * 0.06).normalize()
    const tip = dirOf(a0, clamp(endSy + Math.abs(u) ** 1.4 * 0.14 + rnd() * 0.02, -0.9, 0.9))
    const layer = lay + r * (0.4 + rnd() * 0.8)
    const phase = rnd() * 6
    let rMax = 0
    const pts: THREE.Vector3[] = []
    for (let k = 0; k <= M; k++) {
      const t = k / M
      const d = from.clone().lerp(tip, t).normalize()
      const close = 0.75 * clamp((t - 0.6) / 0.4, 0, 1) ** 1.5
      const a = Math.atan2(d.x, d.z) + (tipAz - a0) * close
      const sy = clamp(d.y, -0.98, 0.999)
      const s = onHeadPolar(p, a, sy, k === 0 ? -r * 2 : layer + R * 0.035 * Math.sin(Math.PI * t))
      const h = Math.hypot(s.pos.x, s.pos.z)
      if (sy < 0 && h < rMax) { s.pos.x *= rMax / h; s.pos.z *= rMax / h }
      rMax = Math.max(rMax, Math.hypot(s.pos.x, s.pos.z))
      pts.push(s.pos)
    }
    out.yarn.push(yarn(pts, r, { mover: m, free: (t) => 0.1 + 0.9 * t ** 1.2, fling: (t) => 0.9 * t ** 1.3, phase }))
  }
}

/** Épi : jaillit derrière le pôle, se courbe en crochet vers l'avant. Tirages faits dans tous les cas. */
function ahoge(p: DollParams, rnd: () => number, r: number, out: Parts) {
  const R = p.shape.headRadius
  const has = rnd() < 0.65
  const root = onDir(p, new THREE.Vector3((rnd() - 0.5) * 0.06, 1, -0.08 - rnd() * 0.1).normalize(), 0, 0.999)
  const H = R * (0.26 + rnd() * 0.14)
  const lean = (rnd() - 0.5) * 0.6
  const fwd = new THREE.Vector3(Math.sin(lean), 0, Math.cos(lean))
  const side = new THREE.Vector3().crossVectors(UP, fwd).normalize()
  const at = (t: number) => root.pos.clone()
    .addScaledVector(root.normal, H * (1.3 * t - 0.6 * t * t))
    .addScaledVector(fwd, H * 0.6 * t ** 1.6)
  const phases = [0, 1, 2, 3].map(() => rnd() * 6)
  if (!has) return
  const tip = at(1)
  const m = out.movers.length
  out.movers.push({ pivot: root.pos.clone(), dir: tip.clone().sub(root.pos).normalize(),
    length: tip.distanceTo(root.pos), cfg: { stiffness: 0.14, drag: 0.07, gravity: 0 }, maxAngle: 0.5 })
  phases.forEach((phase, i) => {
    const u = ((i + 0.5) / 4) * 2 - 1
    const pts = Array.from({ length: 13 }, (_, k) => {
      const t = k / 12
      const q = at(t).addScaledVector(side, u * r * 1.8 * (1 - t) ** 1.2)
      return k === 0 ? q.addScaledVector(root.normal, -r * 2) : q
    })
    out.yarn.push(yarn(pts, r, { mover: m, free: (t) => t ** 1.1, fling: (t) => t, phase }))
  })
}

/**
 * Natte à trois brins : huit décalé d'un tiers de période. Latéral A·sin θ,
 * profondeur B·sin 2θ ; aux croisements, écart 2B·sin(π/3) = 1,73 rs.
 * Lobes alternés dans la silhouette → l'encre les dessine.
 */
function plait(axisAt: (s: number) => THREE.Vector3, len: number, S0: THREE.Vector3, W: number, o: YarnOpts) {
  const rs = W * 0.52, A = W - rs, B = rs, P = W * 4.2
  const N = Math.ceil(len / (W * 0.3))
  const T = new THREE.Vector3(), S = new THREE.Vector3(), D = new THREE.Vector3()
  return [0, 1, 2].map((j) => {
    const pts: THREE.Vector3[] = []
    for (let k = 0; k <= N; k++) {
      const s = (k / N) * len
      const c = axisAt(s)
      T.copy(axisAt(Math.min(len, s + W * 0.2))).sub(axisAt(Math.max(0, s - W * 0.2))).normalize()
      S.copy(S0).addScaledVector(T, -S0.dot(T)).normalize()
      D.crossVectors(T, S)
      const w = (0.7 + 0.3 * smooth(s / (W * 3))) * (1 - 0.3 * smooth((s / len - 0.8) / 0.2))
      const th = (s / P) * Math.PI * 2 + (j * Math.PI * 2) / 3
      pts.push(c.addScaledVector(S, A * w * Math.sin(th)).addScaledVector(D, B * w * Math.sin(2 * th)))
    }
    return yarn(pts, rs, { ...o, step: 0.8, phase: (o.phase ?? 0) + j })
  })
}

/** Nœud : deux boucles en pétale + deux pans, tracés dans (S, U) puis écrasés ×2,4 sur D. */
function bow(c: THREE.Vector3, S: THREE.Vector3, U: THREE.Vector3, D: THREE.Vector3,
  size: number, thread: number, o: YarnOpts): THREE.BufferGeometry[] {
  const place = new THREE.Matrix4().makeBasis(S, U, D).setPosition(c)
    .multiply(new THREE.Matrix4().makeScale(1, 1, 2.4))
  const out: THREE.BufferGeometry[] = []
  for (const sx of [-1, 1]) {
    const loop = Array.from({ length: 13 }, (_, k) => {
      const f = -0.6 + (1.2 * k) / 12 // angle autour du nœud
      const rho = size * Math.cos((f * Math.PI) / 1.2)
      return new THREE.Vector3(sx * rho * Math.cos(f + 0.3), rho * Math.sin(f + 0.3), 0)
    })
    const tailPts = [0, 0.5, 1].map((t) => new THREE.Vector3(sx * size * 0.35 * t, -size * 1.1 * t, 0))
    out.push(yarn(loop, thread, o).applyMatrix4(place), yarn(tailPts, thread, o).applyMatrix4(place))
  }
  return out
}

/** Pinceau sous le lien : s'évase puis se referme en trois pointes. */
function tail(rnd: () => number, r: number, out: Parts, knot: THREE.Vector3, S: THREE.Vector3,
  D: THREE.Vector3, W: number, m: number, f0: number) {
  const Lt = W * (2.4 + rnd() * 1.0)
  const tipLen = [0, 1, 2].map(() => 0.85 + rnd() * 0.3)
  for (let i = 0; i < 15; i++) {
    const c = i % 3
    const phi = (i / 15) * Math.PI * 2 + rnd() * 0.3
    const rad = W * 0.5 * Math.sqrt(rnd())
    const a = (c * Math.PI * 2) / 3 + 0.4
    const tipOff = S.clone().multiplyScalar(Math.cos(a) * W * 0.4).addScaledVector(D, Math.sin(a) * W * 0.4)
    const pts = Array.from({ length: 9 }, (_, k) => {
      const t = k / 8
      const b = rad + W * 0.35 * Math.sin(Math.PI * Math.min(1, t * 1.3))
      const off = S.clone().multiplyScalar(Math.cos(phi) * b).addScaledVector(D, Math.sin(phi) * b)
        .lerp(tipOff, clamp((t - 0.5) / 0.5, 0, 1) ** 1.3)
      return knot.clone().addScaledVector(DOWN, Lt * tipLen[c] * t).add(off)
    })
    out.yarn.push(yarn(pts, r, { mover: m, free: (t) => f0 + (1 - f0) * t, fling: () => 0.8, phase: rnd() * 6 }))
  }
}

function braids(p: DollParams, rnd: () => number, yarnR: number, out: Parts) {
  const R = p.shape.headRadius
  const r = yarnR * 0.9
  const W = yarnR * (3.4 + rnd() * 1.0)
  const az0 = Math.PI / 2 + 0.5 + rnd() * 0.12 // ≥ 2,07 rad : les bras passent devant
  const sy0 = rnd() * 0.2
  out.ribbonColor = RIBBONS[Math.floor(rnd() * RIBBONS.length)]
  const ties = [-1, 1].map((sx) => onHeadPolar(p, sx * az0, sy0, 0))
  pulled(p, rnd, r, ties.map((t) => t.pos), out, NAPE_LOW + rnd() * 0.12, { tuck: W * 0.8 })
  const top = Math.max(r * 0.8, p.shell.height - r * 0.9) + r * 2.2 // dessus de la couche tirée

  const width = 0.85 + rnd() * 0.2
  const tufts = 4 + Math.floor(rnd() * 2)
  const edge = hairline(p, 0, 1.35 + rnd() * 0.4)(0)
  fringeTufts(p, rnd, r, out, {
    width, tufts, edge, sideTo: edge - 0.3, over: () => top, radius: r * 1.1,
    count: () => Math.round(((95 + rnd() * 20) * width) / 1.33),
    cfg: () => ({ stiffness: 0.03 + rnd() * 0.02, drag: 0.08 + rnd() * 0.04, gravity: 0 }),
    maxAngle: 0.2, free: (t) => 0.1 + 0.9 * t ** 1.2, fling: (t) => 0.8 * t ** 1.3,
  })
  const sideEnd = -0.42 - rnd() * 0.15
  for (const sx of [-1, 1] as const) sideLock(p, rnd, r * 1.1, out, sx, sx * (width + 0.12), sideEnd, top)
  ahoge(p, rnd, r * 1.15, out)

  // Longueur déduite des bras (repère du cou → repère de la tête).
  const arms = armSpheres(p, 0, -dollLayout(p).headY).filter((s) => s.center.x > 0).slice(1)
  const armTop = Math.max(...arms.map((s) => s.center.y + s.radius))
  ties.forEach((tie, n) => {
    const radial = new THREE.Vector3(tie.normal.x, 0, tie.normal.z).normalize()
    const S0 = new THREE.Vector3().crossVectors(UP, radial).normalize()
    const axisAt = (s: number) => clearHead(p, tie.pos.clone()
      .addScaledVector(tie.normal, W * 1.2 * smooth(s / (W * 2.5)))
      .addScaledVector(DOWN, Math.max(0, s - W * 0.6)), W * 1.15)
    const L = Math.max(W * 6, (tie.pos.y - armTop) * (0.85 + rnd() * 0.15))
    const m = out.movers.length
    out.movers.push({ pivot: axisAt(W * 0.6), dir: DOWN.clone(), length: L,
      cfg: { stiffness: 0.03 + rnd() * 0.015, drag: 0.14 + rnd() * 0.04, gravity: 1.4 }, maxAngle: 0.4 })
    const free = (t: number) => t ** 1.25
    out.yarn.push(...plait(axisAt, L, S0, W, { mover: m, free, fling: (t) => 0.8 * t, phase: n * 3 }))
    const tan = (s: number) => axisAt(s + W * 0.3).sub(axisAt(Math.max(0, s - W * 0.3))).normalize()
    out.ribbon.push(ring(axisAt(W * 0.6), tan(W * 0.6), W * 0.78 + r * 1.2, r * 1.3)) // tenu
    const tk = 0.93, fk = free(tk), knot = axisAt(L * tk)
    const tied: YarnOpts = { mover: m, free: () => fk, fling: () => 0.8 * tk }
    out.ribbon.push(ring(knot, tan(L * tk), W * 0.62 + r * 1.2, r * 1.3, tied))
    const hasBow = rnd() < 0.6
    const size = W * (1.1 + rnd() * 0.4)
    if (hasBow) out.ribbon.push(...bow(knot, S0, UP, radial, size, r * 1.1, tied))
    tail(rnd, r, out, knot, S0, radial, W, m, fk)
  })
}

sharedBlocks.purpose:
Trois défauts d'échantillonnage mesurés, tous causés par la règle unique « un anneau tous les 3 rayons, plafond 48 » :
- tire-bouchons de « trois poils » : 1,4 à 4,1 anneaux par tour (médiane 2,4, 100 % sous 6), ce qui dessine un bâton en zigzag ;
- anneaux de ruban des couettes, de la queue et des nattes : 6 ou 7 segments, donc des hexagones ou heptagones (800/800 sur 400 graines) ;
- hélice d'une pelote : plafonnée à 48 segments.
La brique permet aussi un tube moins coûteux sur les arcs lisses (step 6 sur les cheveux tirés : −48 % de triangles) et une pointe en trait de pinceau (taper 0,85). Pour les brins ouverts, les valeurs par défaut ne changent pas : la grande frange reste identique au bit près.

