type YarnOpts = { closed?: boolean; mover?: number; free?: (t: number) => number; fling?: (t: number) => number; phase?: number; braid?: boolean; /** anneau tous les `step` rayons (3) */ step?: number; /** nombre d'anneaux imposé (spirales) */ segs?: number; /** part effilée (0,2) */ taper?: number }
function yarn(points: THREE.Vector3[], radius: number, o?: YarnOpts): THREE.BufferGeometry
function ring(center: THREE.Vector3, axis: THREE.Vector3, radius: number, thread: number, o?: YarnOpts): THREE.BufferGeometry

