function onDir(p, d, lift, cap = 0.98) {
  return onHeadPolar(p, Math.atan2(d.x, d.z), clamp(d.y, -0.98, cap), lift)
}
const after = (t0: number) => (t: number) => clamp((t - t0) / Math.max(1e-3, 1 - t0), 0, 1)

function faceSafe(p: DollParams) {
  const R = p.shape.headRadius, ry = R * p.shape.headSquash
