    // sy du bord de frange au facteur f : même loi que hairline(p, 0, f)(0)
    edge: (f: number) => clamp((p.face.eyeHeight + size * f) / ry, 0.3, 0.85),
    // Pivot au centre : la pointe glisse de R·a·free. Elle ne descend jamais sur un bouton.
    maxAngle: (edgeSy: number, freeMax = 1) => clamp((0.8 * (edgeSy * ry - buttonTop)) / (R * freeMax), 0.04, 0.3),
