function hairlineAt(low: number, front: number) {
  return (az: number) => {
    const w = clamp((Math.max(0, Math.cos(az)) - 0.25) / 0.6, 0, 1)
    return low + (Math.max(front, low) - low) * w * w * (3 - 2 * w)
  }
}
function pulled(p, rnd, r, targets, out, low, o: PulledOpts = {}) {
  const R = p.shape.headRadius, CAP = 0.9995
  const limit = o.crown !== undefined ? hairlineAt(low, o.crown) : hairline(p, low)
  const rim = (az: number) => dirOf(az, limit(az) + 0.02 - Math.max(0, -Math.cos(az)) ** 3 * 0.18)
  const dirs = targets.map((t) => t.clone().normalize())
  const nearest = (f: THREE.Vector3) => dirs.reduce((a, d) => (d.dot(f) > a.dot(f) ? d : a), dirs[0])
  const split = dirs.length === 2 && dirs[0].x * dirs[1].x < 0
  const a0 = Math.asin(limit(0)), a1 = Math.PI - Math.asin(Math.max(-0.9, limit(Math.PI) - 0.1))
  const zones = split
    ? dirs.map((to) => { const s = Math.sign(to.x)
        const part = Array.from({ length: 121 }, (_, k) => { const a = a0 + ((a1 - a0) * k) / 120; return new THREE.Vector3(s * 0.02, Math.sin(a), Math.cos(a)).normalize() })
        const edge = Array.from({ length: 180 }, (_, k) => rim(s * (Math.PI - (Math.PI * (k + 1)) / 181)))
        return { to, line: [...part, ...edge] } })
    : [{ to: null, line: Array.from({ length: 721 }, (_, k) => rim(-Math.PI + (k / 720) * Math.PI * 2)) }]
  const base = Math.max(r * 0.8, p.shell.height - r * 0.9)
  for (const z of zones) {
    const pos = z.line.map((d) => onDir(p, d, 0, CAP).pos)
    const cum = [0]
    for (let i = 1; i < pos.length; i++) {
      const th = z.line[i].angleTo(z.to ?? nearest(z.line[i]))
      cum.push(cum[i - 1] + pos[i].distanceTo(pos[i - 1]) / (th > Math.PI / 2 ? Math.max(0.3, Math.sin(th)) : 1))
    }
    const B = cum[cum.length - 1]
    const n = clamp(Math.ceil(B / ((o.pitch ?? 1.8) * r)), 60, 480)
    for (let i = 0, j = 1; i < n; i++) {
      const at = ((i + 0.5 + (rnd() - 0.5) * 0.3) / n) * B
      while (j < cum.length - 1 && cum[j] < at) j++
      const from = z.line[j - 1].clone().lerp(z.line[j], clamp((at - cum[j - 1]) / Math.max(1e-9, cum[j] - cum[j - 1]), 0, 1)).normalize()
      const to = z.to ?? nearest(from)
      const upper = i % 2 === 1
      const ridge = upper && o.grooves ? r * 0.9 * (0.5 + 0.5 * Math.cos((2 * Math.PI * o.grooves * at) / B)) : 0
      const layer = upper ? base + r * (0.9 + rnd() * 0.3) + ridge : base * (1 + rnd() * 0.2)
      const ang = from.angleTo(to)
      const reach = o.tuck ? Math.max(0.2, 1 - o.tuck / Math.max(ang, 1e-3)) : 1
      const M = clamp(Math.ceil(ang / 0.08), 8, 24)
      const pts: THREE.Vector3[] = []
      for (let k = 0; k <= M; k++) {
        const d = from.clone().lerp(to, (k / M) * reach).normalize()
        pts.push(onDir(p, d, k === 0 ? -r * 2 : k === M && o.tuck ? -r * 0.5 : layer, CAP).pos)
      }
      out.yarn.push(yarn(pts, r, { step: 6 })) // aucune option de mouvement : aMover −1, aFree = aFling = 0
    }
  }
  return { frontLine: (az: number) => limit(az) + 0.02 }
}

sharedBlocks.purpose:
C'est la frange que l'utilisateur aime : deux rangées de mèches décalées d'une demi-mèche, pointes convergentes à 0,6, bords plus courts, allongement vers les tempes, décollement, retombée.

**Extraction.** On l'extrait telle quelle, et bangs() l'appelle. C'est un refactor **pur** : même ordre de tirages et même géométrie, vérifié par empreinte des positions sur 50 graines. On ne la recopie pas : deux copies finissent par diverger, c'est la règle de CLAUDE.md.

**Paramètres ajoutés, pour que les fronts d'une planche se distinguent** :
- `sweep` pour une frange de côté ;
- `split` pour une frange rideau ;
- `root` pour prendre les racines sur la raie (bangs) ou sur la lisière relevée de pulled (coupes tirées) ; la frange part alors vers l'avant de la même ligne d'où les tirés partent vers l'arrière, sans recouvrement ni « base » ;
- `minAngle` pour ne pas poser les brins trop courts.

**Physique des franges courtes** :
- un ressort par mèche, pivot au centre, sans gravité ;
- racine tenue par after(0,15) : elle borde des cheveux immobiles, une racine qui glisse lirait comme une perruque ;
- maxAngle déduit de faceSafe.maxAngle(edge), jamais réglé à la main.

