function fringeTufts(p, rnd, r, out, o) {
  const R = p.shape.headRadius, f0 = out.movers.length
  for (let k = 0; k < o.tufts; k++) {
    const ac = (((k + 0.5) / o.tufts) * 2 - 1) * o.width * 0.92 + (o.sweep ?? 0)
    out.movers.push({ pivot: new THREE.Vector3(), dir: new THREE.Vector3(Math.sin(ac) * 0.75, -0.66, Math.cos(ac) * 0.75).normalize(), length: R, cfg: o.cfg(), maxAngle: o.maxAngle })
  }
  const count = o.count()                        // ordre de bangs conservé
  const tuftLen = Array.from({ length: o.tufts }, () => rnd())
  for (let i = 0; i < count; i++) {
    // corps de bangs l. 1218-1292, avec o.* à la place des constantes, plus :
    let tipAz = az + (center - az) * 0.6
    if (o.split) tipAz += Math.sign(tipAz || 1) * o.split * (1 - Math.abs(tipAz) / o.width)
    if (o.sweep) tipAz += o.sweep * (1 - side * side)
    let tipSy = o.edge + tuftLen[c] * 0.05 + Math.abs(w) ** 1.5 * 0.06 + rnd() * 0.015 - lengthen
    if (o.split) tipSy += o.split * 0.5 * (1 - side)              // rideau : le centre s'ouvre en V renversé
    if (o.sweep) tipSy -= Math.abs(o.sweep) * 0.3 * (Math.sign(o.sweep) * tipAz) / o.width // le côté balayé descend
    const from = o.root(tipAz, rnd() - 0.5)                        // même rang de tirage que bangs
    const tip = dirOf(tipAz, clamp(tipSy, -0.9, 0.9))
    const layer = r * (0.8 + rnd() * 2.2) + o.over(side)
    if ((o.minAngle ?? 0) > 0 && from.angleTo(tip) < o.minAngle!) { rnd(); continue } // phase tirée quand même
    // … tracé, retombée si o.hang …
    out.yarn.push(yarn(pts, o.radius, { mover: f0 + c, free: o.free, fling: o.fling, phase: rnd() * 6 }))
  }
}
// bangs() : fringeTufts(p, rnd, r, out, { width, tufts, edge, sideTo: longEnd, lengthenFrom: 0.55,
//   root: (a, j) => new THREE.Vector3(Math.sign(a || 1) * 0.03, 1, Math.cos(a) * 0.55 - 0.12 + j * 0.08).normalize(),
//   over: (s) => FRINGE_OVER * R * clamp((s - 0.35) / 0.5, 0, 1), count: () => { rnd(); return 110 + Math.floor(rnd() * 20) },
//   radius: r * 1.15, cfg: () => ({ stiffness: 0.018 + rnd() * 0.02, drag: 0.05 + rnd() * 0.05, gravity: 0 }),
//   maxAngle: 0.42, free: (t) => 0.4 + 0.6 * t, fling: (t) => t, hang: true })

function sideLock(p, rnd, r, out, sx, o) {
  const R = p.shape.headRadius, m = out.movers.length
  out.movers.push({ pivot: new THREE.Vector3(), dir: new THREE.Vector3(Math.sin(o.az) * 0.75, -0.66, Math.cos(o.az) * 0.75).normalize(),
    length: R, cfg: { stiffness: 0.03 + rnd() * 0.015, drag: 0.08 + rnd() * 0.04, gravity: 0 }, maxAngle: o.maxAngle })
  const tipAz = o.az - sx * o.curl
  const hangLen = (o.hang ?? 0) * (0.8 + rnd() * 0.2)
  for (let i = 0; i < o.strands; i++) {
    const u = ((i + 0.5) / o.strands) * 2 - 1, a0 = o.az + u * o.span * 0.5
    const from = o.root(a0)
    const tip = dirOf(a0, clamp(o.endSy + Math.abs(u) ** 1.4 * 0.14 + rnd() * 0.02, -0.9, 0.9))
    const layer = o.over + r * (0.4 + rnd() * 0.8), phase = rnd() * 6
    let rMax = 0; const pts: THREE.Vector3[] = []
    for (let k = 0; k <= 18; k++) {
      const t = k / 18, d = from.clone().lerp(tip, t).normalize()
      const close = 0.8 * clamp((t - 0.6) / 0.4, 0, 1) ** 1.5
      const sy = clamp(d.y, -0.98, 0.9995)
      const s = onHeadPolar(p, Math.atan2(d.x, d.z) + (tipAz - a0) * close, sy, k === 0 ? -r * 2 : layer + R * 0.035 * Math.sin(Math.PI * t))
      const h = Math.hypot(s.pos.x, s.pos.z)
      if (sy < 0 && h < rMax) { s.pos.x *= rMax / h; s.pos.z *= rMax / h }
      rMax = Math.max(rMax, Math.hypot(s.pos.x, s.pos.z)); pts.push(s.pos)
    }
    if (hangLen > 0) { const last = pts[pts.length - 1]
      for (let k = 1; k <= 5; k++) pts.push(clearHead(p, last.clone().addScaledVector(DOWN, (hangLen * k) / 5), r * 2)) }
    out.yarn.push(yarn(pts, r * 1.1, { mover: m, free: (t) => after(0.15)(t) ** 1.2, fling: (t) => 0.9 * t ** 1.3, phase }))
  }
}

function ahoge(p, rnd, r, out, prob) {
  const has = rnd() < prob
  const sub = mulberry32(Math.floor(rnd() * 1e9))
  if (!has) return
  const R = p.shape.headRadius
  const root = onDir(p, new THREE.Vector3((sub() - 0.5) * 0.06, 1, -0.08 - sub() * 0.1).normalize(), 0, 0.9995)
  const H = R * (0.26 + sub() * 0.14), lean = (sub() - 0.5) * 0.6
  const fwd = new THREE.Vector3(Math.sin(lean), 0, Math.cos(lean)), side = new THREE.Vector3().crossVectors(UP, fwd).normalize()
  const at = (t: number) => root.pos.clone().addScaledVector(root.normal, H * (1.3 * t - 0.6 * t * t)).addScaledVector(fwd, H * 0.6 * t ** 1.6)
