  out.movers.push({ pivot: root.pos.clone(), dir: tip.clone().sub(root.pos).normalize(), length: tip.distanceTo(root.pos),
    cfg: { stiffness: 0.14 + sub() * 0.04, drag: 0.06 + sub() * 0.01, gravity: 0 }, maxAngle: 0.5 })
  for (let i = 0; i < 4; i++) {
    const u = ((i + 0.5) / 4) * 2 - 1
    const pts = Array.from({ length: 13 }, (_, k) => { const t = k / 12
      const q = at(t).addScaledVector(side, u * r * 1.8 * (1 - t) ** 1.2)
      return k === 0 ? q.addScaledVector(root.normal, -r * 2) : q })
    out.yarn.push(yarn(pts, r * 1.1, { mover: m, free: (t) => t ** 1.1, fling: (t) => 0.5 * t, phase: sub() * 6, taper: 0.5 }))
  }
}

